from pathlib import Path
import json,html,shutil
r=Path(__file__).resolve().parents[1]
chapters=[
('2013','Sharif University','Learning to see the Earth differently','sharif','Research foundations',"My PhD began at Sharif in 2013. My early introduction to GIS and remote sensing gave me a new way to ask questions about water. I started with ArcGIS and began learning MATLAB.",['GIS & ArcGIS','Remote sensing','MATLAB foundations'],'Mapping and interpreting satellite observations.'),
('2015–2019','Building a startup','Turning an idea into a product','startup','Entrepreneurship',"Alongside my PhD, I co-founded a company in 2015. Courses on entrepreneurship helped us move from ideas to products and minimum viable products. I designed website experiences for satellite-based agricultural monitoring and rural tourism, using PowerPoint to prototype interfaces and create presentation videos. We dissolved the company in 2019, but the design and communication skills stayed with me.",['MVP development','UX prototyping','Visual storytelling'],'Product concepts, two website UX designs and presentation videos.'),
('2016–2017','CNR IRPI · Italy','From scripts to reusable models','italy','Research collaboration',"In Italy, I strengthened my MATLAB skills while processing satellite imagery. I learned to build models, write functions and assemble reusable components into modular software. Coding became a way to develop and test scientific ideas.",['Satellite image processing','Model development','Modular programming'],'Reusable functions and satellite-processing workflows.'),
('2018','Teaching at Sharif','Learning by explaining','sharif','Teaching',"Teaching at Sharif gave me another way to work with ideas: explain them clearly, organize them into a course and help others develop their own understanding.",['Teaching','Scientific communication'],'University teaching alongside my doctoral research.'),
('2019','PhD completed','Carrying the experience forward','sharif','Milestone',"I completed my PhD in 2019. The same year, our company closed. Research, coding and product design had become connected parts of my experience, ready to carry into the next stage.",[],'A PhD and experience spanning research, software and product design.'),
('2020','First postdoctoral role','From satellite data to land models','sharif','Research & computing',"My first postdoctoral role introduced me to the VIC model, land surface modeling and data assimilation. I began working in Ubuntu and Linux, using the command line and Bash scripts. I used MATLAB to preprocess satellite data and prepare model inputs.",['Linux & Ubuntu','Command line & Bash','VIC & land surface modeling','Data assimilation'],'Satellite data prepared for modeling and assimilation experiments.'),
('2020–2021','Teaching & Earth science','Making knowledge accessible online','sharif','Teaching & faculty',"In 2020 and 2021, I taught at Amirkabir University and learned Google Earth Engine while teaching a master’s course. Teaching through the pandemic also meant learning to record lessons, which led me to start a YouTube channel. In 2021, I became a faculty member at the Research Institute for Earth Sciences, before moving to the United States.",['Google Earth Engine','Recorded teaching','YouTube communication'],'Online lessons, a YouTube channel and an Earth-science faculty role.'),
('2022','Michigan State University','Scaling up—and moving to Python','michigan','Postdoctoral research',"At Michigan State, I was introduced to high-performance computing. My online master’s studies in analytics at Georgia Tech also helped me learn Python. I moved from MATLAB toward Python, building confidence with NumPy and pandas, then expanding into machine learning with scikit-learn and PyTorch.",['High-performance computing','Python','NumPy & pandas','scikit-learn','PyTorch'],'Larger computing workflows and a growing Python and machine-learning toolkit.'),
('2023–present','NASA Goddard','Building research software and global products','nasa','Research scientist',"At NASA, I deepened my use of Git and GitHub, developed within NASA’s Land Information System (LIS) using Fortran, and learned to build Python software packages through AgroTrack. I developed my first global soil-moisture product using machine learning. The work expanded both the scientific questions I could tackle and the software skills I needed to answer them.",['Git & GitHub','NASA LIS & Fortran','AgroTrack Python package','Global ML products'],'A global machine-learning soil-moisture product and reusable research software.'),
('Recent work','NASA · continuing to learn','From foundation models to agents','nasa','Ongoing development',"More recently, I have learned to fine-tune geospatial foundation models and benchmark them against one another. I am also exploring agents to automate everyday work, from software development to building this website and maintaining its research information. Each new need becomes a reason to learn the next skill.",['Geospatial foundation models','Fine-tuning & benchmarking','Agent workflows'],'Foundation-model experiments and automation for research and everyday development.')]
esc=html.escape
articles=[];timeline=[]
for i,(year,place,title,stop,kind,copy,skills,output) in enumerate(chapters):
 timeline.append(f'<li><button class="time-stop" data-stage="{i}" aria-controls="chapter-{i}"><span>{esc(year)}</span><strong>{esc(place.split(" · ")[0])}</strong><small>{esc(kind)}</small></button></li>')
 tags=''.join(f'<li>{esc(v)}</li>' for v in skills) or '<li class="milestone-tag">Consolidating earlier skills</li>'
 articles.append(f'<article class="chapter" id="chapter-{i}" data-landmark="{stop}" data-skills="{esc(json.dumps(skills),quote=True)}"><div class="chapter-side"><p class="eyebrow">{esc(kind)}</p><p class="chapter-date">{esc(year)}</p><p>{esc(place)}</p></div><div><h2>{esc(title)}</h2><p class="chapter-copy">{esc(copy)}</p><p class="small-title">Skills added</p><ul class="skill-tags">{tags}</ul><p class="chapter-output"><b>What this enabled</b> {esc(output)}</p></div></article>')
landmarks=[('sharif','Sharif & early research',0,'8%;--y:41%;--w:30%;--h:28%'),('startup','Startup',1,'30%;--y:61%;--w:13%;--h:17%'),('italy','CNR IRPI · Italy',2,'42%;--y:38%;--w:18%;--h:22%'),('michigan','Michigan State',7,'66%;--y:32%;--w:11%;--h:36%'),('nasa','NASA Goddard',8,'80%;--y:12%;--w:17%;--h:29%')]
spots=''.join(f'<button class="map-stop" data-landmark="{key}" data-stage="{stage}" style="--x:{pos}" aria-label="Explore {esc(label)}"><span class="ground-glow"></span><span class="map-label">{esc(label)}<span aria-hidden="true"> ↗</span></span></button>' for key,label,stage,pos in landmarks)
out='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My learning journey | Ehsan Jalilvand</title><meta name="description" content="How Ehsan Jalilvand’s skills grew through research, entrepreneurship, teaching and scientific software, from Sharif to NASA."><link rel="stylesheet" href="assets/journey-v2.css"><script src="assets/journey-v2.js" defer></script></head><body><a class="skip" href="#timeline">Skip to timeline</a><header class="site-header"><a href="index.html">Ehsan Jalilvand</a><nav aria-label="Main"><a href="index.html#explore">Water cycle</a><a href="index.html#studies">Irrigation studies</a><a href="https://www.ehsanjalilvand.com/cv-publications">CV & publications ↗</a></nav></header><main><div class="intro"><div><p class="eyebrow">A journey of learning · 2013 to today</p><h1>One skill leads<br>to the next.</h1></div><p>From my first GIS maps to scientific models, machine learning and agents. A journey shaped by research questions, new roles, and learning what the next challenge required.</p></div><section aria-label="Explore the journey landscape"><div class="map"><img src="assets/journey/landscape-integrated-v2.webp" width="1672" height="941" alt="A symbolic landscape linking Sharif and Tehran landmarks, a small startup workshop, Italy’s Colosseum, Michigan State’s clocktower, and a NASA rocket and research building. The landmarks sit along paths in one continuous terrain.">'''+spots+'''</div><div class="map-caption"><span>Hover or focus to highlight a place. Select it to explore.</span><span>Illustrated landmarks · symbolic geography</span></div></section><section class="timeline-section" id="timeline" aria-labelledby="timeline-title"><div class="section-heading"><div><p class="eyebrow">Places change. Skills accumulate.</p><h2 id="timeline-title">Follow the timeline</h2></div><div class="step-controls" hidden><button id="previous" aria-label="Previous stage">←</button><span id="step-count" aria-live="polite"></span><button id="next" aria-label="Next stage">→</button></div></div><p class="timeline-help">Select a year to see what I learned and what it made possible. Some chapters overlap.</p><ol class="timeline">'''+''.join(timeline)+'''</ol><div id="chapter-list">'''+''.join(articles)+'''</div><section class="toolkit" aria-labelledby="toolkit-title" hidden><div><p class="eyebrow">Building on what came before</p><h3 id="toolkit-title">My toolkit at this stage</h3><p>New additions are highlighted.</p></div><ul id="accumulated-skills" class="skill-tags"></ul></section></section><footer><p>Research, teaching and building things have always informed one another.</p><a href="https://science.gsfc.nasa.gov/600/ECSS/Ehsan-Jalilvand/">Read my NASA career spotlight ↗</a><p class="fine">This is my personal journey; views expressed here are my own.</p></footer></main></body></html>'''
(r/'journey.html').write_text(out)
(r/'data/journey-timeline.json').write_text(json.dumps([dict(zip(['period','place','title','landmark','category','story','skills','outcome'],c)) for c in chapters],indent=2)+'\n')
